(7262304, 1129659, 174999, '<td valign="top">Another one of my tops.. who doesn''t like legos</td>', 'Another one of my tops.. who doesn''t like legos', '2014-09-12 04:40:35.000000', NULL, 1),
(7262305, 1129189, 174999, '<td valign="top">Very true! Awesome landscape</td>', 'Very true! Awesome landscape', '2014-09-12 04:41:35.000000', NULL, 1),
(7262307, 1129647, 174999, '<td valign="top">I don''t care for zombies, but this is best in show, my blue and my top favorite, Very well done the colors and tone just work for this post and the dirty look.</td>', 'I don''t care for zombies, but this is best in show, my blue and my top favorite, Very well done the colors and tone just work for this post and the dirty look.', '2014-09-12 04:47:57.000000', NULL, 1),
(7262340, 1129660, 118154, '<td valign="top">The owner of this shows a fine mind with quirks. I lie it.</td>', 'The owner of this shows a fine mind with quirks. I lie it.', '2014-09-12 09:36:35.000000', NULL, 1),
(7262345, 1129567, 156466, '<td valign="top">Call the font police.  Too many, and Comic Sans not once but twice.  The boat photo is nice though.</td>', 'Call the font police.  Too many, and Comic Sans not once but twice.  The boat photo is nice though.', '2014-09-12 09:59:31.000000', NULL, 1),
(7262346, 1129189, 156466, '<td valign="top">Nice photo, but I''m not a fan of the text placement</td>', 'Nice photo, but I''m not a fan of the text placement', '2014-09-12 10:04:09.000000', NULL, 1),
(7262347, 1129326, 156466, '<td valign="top">Another "call the font police" poster.  Too many fonts, too many effects.</td>', 'Another "call the font police" poster.  Too many fonts, too many effects.', '2014-09-12 10:04:55.000000', NULL, 1),
(7262349, 1129645, 13077, '<td valign="top">I like how you have the cheery, colorful lettering on top of the photo with a texture that makes it look like an old tattered and stained print.</td>', 'I like how you have the cheery, colorful lettering on top of the photo with a texture that makes it look like an old tattered and stained print.', '2014-09-12 10:07:21.000000', NULL, 1),
(7262350, 1129659, 156466, '<td valign="top">Well done but the colors seem a touch muted/yellowed.  Was that intentional?</td>', 'Well done but the colors seem a touch muted/yellowed.  Was that intentional?', '2014-09-12 10:07:54.000000', NULL, 1),
(7262351, 1129456, 156466, '<td valign="top">Nice photo treatment.  Not so much with the slogan and text - at least for me.  I''m not talking about the message, I''m talking about the actual verbiage and text spacing.  Lots of empty space and skewed text.  I would have included the title on the poster.</td>', 'Nice photo treatment.  Not so much with the slogan and text - at least for me.  I''m not talking about the message, I''m talking about the actual verbiage and text spacing.  Lots of empty space and skewed text.  I would have included the title on the poster.', '2014-09-12 10:10:22.000000', NULL, 1),
(7262352, 1129636, 156466, '<td valign="top">Not digging the distortion of the eyes.</td>', 'Not digging the distortion of the eyes.', '2014-09-12 10:11:21.000000', NULL, 1),
(7262353, 1129270, 156466, '<td valign="top">Head seems too small for the helmet.  Otherwise nicely done, though I think you have one too many fonts on the bottom line.</td>', 'Head seems too small for the helmet.  Otherwise nicely done, though I think you have one too many fonts on the bottom line.', '2014-09-12 10:12:45.000000', NULL, 1),
(7262354, 1129229, 156466, '<td valign="top">A different font (and uncurved) in the middle and this would have looked rather professional.</td>', 'A different font (and uncurved) in the middle and this would have looked rather professional.', '2014-09-12 10:14:06.000000', NULL, 1),
(7262355, 1129549, 156466, '<td valign="top">Would like to see a little more contrast in the photo.  Need to be mindful of font sizes at 800px - we like to read fine print.</td>', 'Would like to see a little more contrast in the photo.  Need to be mindful of font sizes at 800px - we like to read fine print.', '2014-09-12 10:15:21.000000', NULL, 1),
(7262356, 1129645, 156466, '<td valign="top">Just because textures are allowed it doesn''t mean you have to use them.  I assume you''re trying to use them as evidence of earth-abuse but to me they''re just distracting.</td>', 'Just because textures are allowed it doesn''t mean you have to use them.  I assume you''re trying to use them as evidence of earth-abuse but to me they''re just distracting.', '2014-09-12 10:17:14.000000', NULL, 1),
(7262357, 1129657, 156466, '<td valign="top">The bottom text running precisely at the bottom of the photo doesn''t appeal to me.  Move it up, move it down - just move it.<br/> <br/>Cute kid.</td>', 'The bottom text running precisely at the bottom of the photo doesn''t appeal to me.  Move it up, move it down - just move it. Cute kid.', '2014-09-12 10:19:55.000000', NULL, 1),
(7262358, 1129655, 156466, '<td valign="top">If you''ve got something to say it needs to be readable, even when your point is that stuff is hidden.</td>', 'If you''ve got something to say it needs to be readable, even when your point is that stuff is hidden.', '2014-09-12 10:21:07.000000', NULL, 1),
(7262359, 1129560, 156466, '<td valign="top">Over-saturated.  In all sorts of ways.</td>', 'Over-saturated.  In all sorts of ways.', '2014-09-12 10:21:56.000000', NULL, 1),
(7262360, 1129623, 156466, '<td valign="top">Nice treatment but I really don''t like the mixed text orientations.  Top would be better centered like the bottom or spaced so that it squares on both sides, not just on the left.</td>', 'Nice treatment but I really don''t like the mixed text orientations.  Top would be better centered like the bottom or spaced so that it squares on both sides, not just on the left.', '2014-09-12 10:23:10.000000', NULL, 1),
(7262365, 1129561, 156466, '<td valign="top">Funny.  Not a fan of the 3D text with the blurred kitty.</td>', 'Funny.  Not a fan of the 3D text with the blurred kitty.', '2014-09-12 10:26:18.000000', NULL, 1),
(7262372, 1129636, 13077, '<td valign="top">The expression on his face is funny. It would have been cool if you found a little alien ship toy to put in there too.</td>', 'The expression on his face is funny. It would have been cool if you found a little alien ship toy to put in there too.', '2014-09-12 10:49:24.000000', NULL, 1),
(7262373, 1129657, 13077, '<td valign="top">I would have centered the photo more in the frame. The selective coloring to red matches the color scheme well, and the face she''s making makes her look tough.</td>', 'I would have centered the photo more in the frame. The selective coloring to red matches the color scheme well, and the face she''s making makes her look tough.', '2014-09-12 10:51:12.000000', NULL, 1),
(7262374, 1129617, 13077, '<td valign="top">I don''t get the connection to google on this one.</td>', 'I don''t get the connection to google on this one.', '2014-09-12 10:51:45.000000', NULL, 1),
(7262375, 1129561, 13077, '<td valign="top">Cute.</td>', 'Cute.', '2014-09-12 10:52:05.000000', NULL, 1),
(7262376, 1129647, 13077, '<td valign="top">This is really well done and funny. You could probably sell these if you made actual posters.</td>', 'This is really well done and funny. You could probably sell these if you made actual posters.', '2014-09-12 10:52:44.000000', NULL, 1),
(7262377, 1129642, 13077, '<td valign="top">I don''t really get it.</td>', 'I don''t really get it.', '2014-09-12 10:53:35.000000', NULL, 1),
(7262378, 1129619, 13077, '<td valign="top">I''m sure this took a lot of work and it paid off, well done.</td>', 'I''m sure this took a lot of work and it paid off, well done.', '2014-09-12 10:55:26.000000', NULL, 1),
(7262379, 1129620, 13077, '<td valign="top">I had to google the phrase... Not sure this was the best photo to use for it, or maybe I just don''t get it.</td>', 'I had to google the phrase... Not sure this was the best photo to use for it, or maybe I just don''t get it.', '2014-09-12 10:57:52.000000', NULL, 1),
(7262380, 1129659, 13077, '<td valign="top">Cute - well done.</td>', 'Cute - well done.', '2014-09-12 10:58:24.000000', NULL, 1),
(7262382, 1129578, 13077, '<td valign="top">I''m not familiar with the cultural reference and I can''t read the text, but it''s well composed and edited. Not sure the yellow colored light at the top right adds anything, though.</td>', 'I''m not familiar with the cultural reference and I can''t read the text, but it''s well composed and edited. Not sure the yellow colored light at the top right adds anything, though.', '2014-09-12 11:00:08.000000', NULL, 1),
(7262383, 1129537, 13077, '<td valign="top">Your crop left a white strip at the far right, not sure if that was intentional. I think another font would have worked better.</td>', 'Your crop left a white strip at the far right, not sure if that was intentional. I think another font would have worked better.', '2014-09-12 11:02:24.000000', NULL, 1),
(7262384, 1129557, 13077, '<td valign="top">Given that it''s expert editing, some kind of processing on the photo, if nothing else to make the text able to stand out better, would have helped.</td>', 'Given that it''s expert editing, some kind of processing on the photo, if nothing else to make the text able to stand out better, would have helped.', '2014-09-12 11:03:25.000000', NULL, 1),
(7262385, 1129457, 13077, '<td valign="top">Simple composition and styling, but the pose looks awkward to me and it could have used more sharpening on the man.</td>', 'Simple composition and styling, but the pose looks awkward to me and it could have used more sharpening on the man.', '2014-09-12 11:04:46.000000', NULL, 1),
(7262387, 1129229, 13077, '<td valign="top">Well put together and solid, could work well as an actual promotion for historic sites. Only thing I might have changed is make the word "historical" "historic", like your title and the plaque.</td>', 'Well put together and solid, could work well as an actual promotion for historic sites. Only thing I might have changed is make the word "historical" "historic", like your title and the plaque.', '2014-09-12 11:06:51.000000', NULL, 1),
(7262388, 1129639, 13077, '<td valign="top">I think the cheerful font doesn''t quite match the overall tone set by the skull and the eery green color.</td>', 'I think the cheerful font doesn''t quite match the overall tone set by the skull and the eery green color.', '2014-09-12 11:07:41.000000', NULL, 1),
(7262395, 1129654, 13077, '<td valign="top">Well put together and attractive for the most part. I might have recommended more blur on the fill layer for the main text at the top.</td>', 'Well put together and attractive for the most part. I might have recommended more blur on the fill layer for the main text at the top.', '2014-09-12 11:23:59.000000', NULL, 1),
(7262396, 1129635, 13077, '<td valign="top">Well done. Simple and communicates the message well.</td>', 'Well done. Simple and communicates the message well.', '2014-09-12 11:24:31.000000', NULL, 1),
(7262397, 1129633, 13077, '<td valign="top">I can''t read it, but visually I think it''s put together well.</td>', 'I can''t read it, but visually I think it''s put together well.', '2014-09-12 11:25:04.000000', NULL, 1),
(7262398, 1129650, 13077, '<td valign="top">I don''t get the phrase. The text and effects look good though.</td>', 'I don''t get the phrase. The text and effects look good though.', '2014-09-12 11:26:07.000000', NULL, 1),
(7262399, 1129432, 13077, '<td valign="top">Simple and striking, well done.</td>', 'Simple and striking, well done.', '2014-09-12 11:26:42.000000', NULL, 1),
(7262401, 1129662, 13077, '<td valign="top">I think the message would have worked better if the dogs had been running free and not on leashes and/or being held.</td>', 'I think the message would have worked better if the dogs had been running free and not on leashes and/or being held.', '2014-09-12 11:27:58.000000', NULL, 1),
(7262403, 1129549, 13077, '<td valign="top">I don''t think the small template-like text at the bottom is adding anything. Also, why such a dark sky in the background?</td>', 'I don''t think the small template-like text at the bottom is adding anything. Also, why such a dark sky in the background?', '2014-09-12 11:29:12.000000', NULL, 1),
(7262404, 1129623, 13077, '<td valign="top">I think the a regular non-cursive font might have helped this, but I like the layout and color scheme. Also the editing looks pretty cool.</td>', 'I think the a regular non-cursive font might have helped this, but I like the layout and color scheme. Also the editing looks pretty cool.', '2014-09-12 11:30:20.000000', NULL, 1),
(7262405, 1129660, 13077, '<td valign="top">The tones and effects on this look really good, well done.</td>', 'The tones and effects on this look really good, well done.', '2014-09-12 11:31:02.000000', NULL, 1),
(7262407, 1129626, 13077, '<td valign="top">Nice title. lol</td>', 'Nice title. lol', '2014-09-12 11:31:26.000000', NULL, 1),
(7262409, 1129189, 13077, '<td valign="top">With just the quote, it seems almost like a motivational poster. I think a message against some kind of environmental damage, combined with the quote, would have brought some propaganda into it.</td>', 'With just the quote, it seems almost like a motivational poster. I think a message against some kind of environmental damage, combined with the quote, would have brought some propaganda into it.', '2014-09-12 11:33:09.000000', NULL, 1),
(7262410, 1129648, 13077, '<td valign="top">Well-lit for sure, but maybe some bolder, green colored letters for the word "VEGGIES" would have looked better instead of using the same font as the top.</td>', 'Well-lit for sure, but maybe some bolder, green colored letters for the word "VEGGIES" would have looked better instead of using the same font as the top.', '2014-09-12 11:34:09.000000', NULL, 1),
(7262411, 1129270, 13077, '<td valign="top">Nicely done. Where can I sign up? oh wait...</td>', 'Nicely done. Where can I sign up? oh wait...', '2014-09-12 11:34:47.000000', NULL, 1),
(7262412, 1129560, 13077, '<td valign="top">Wow. Sends a strong message, I imagine you might catch some flack for what covers the stars on the flag though.</td>', 'Wow. Sends a strong message, I imagine you might catch some flack for what covers the stars on the flag though.', '2014-09-12 11:35:54.000000', NULL, 1),
(7262413, 1129339, 13077, '<td valign="top">Excellent editing, I hope you will post a how-to on this one. I would love to try it out.</td>', 'Excellent editing, I hope you will post a how-to on this one. I would love to try it out.', '2014-09-12 11:36:42.000000', NULL, 1),
(7262417, 1129456, 13077, '<td valign="top">The editing looks good. I wonder if it might have worked better just having the word "PROHIBITION" with a red circle and cross through it though?</td>', 'The editing looks good. I wonder if it might have worked better just having the word "PROHIBITION" with a red circle and cross through it though?', '2014-09-12 11:40:29.000000', NULL, 1),
(7262418, 1129655, 13077, '<td valign="top">I like the double exposure and processing styles. I wish the text overlaying it was a little more legible though.</td>', 'I like the double exposure and processing styles. I wish the text overlaying it was a little more legible though.', '2014-09-12 11:41:17.000000', NULL, 1),
(7262433, 1129567, 13077, '<td valign="top">lol</td>', 'lol', '2014-09-12 11:57:28.000000', NULL, 1),
(7262443, 1129270, 113016, '<td valign="top">wonderful!  beautiful texture</td>', 'wonderful!  beautiful texture', '2014-09-12 12:17:11.000000', NULL, 1),
