INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7264492, 1129655, 19825, '<td valign="top">This was in my top two -- I''m sorry I did not get back to comment on this. Fantastic and compelling image -- beautifully stylized.</td>', 'This was in my top two -- I''m sorry I did not get back to comment on this. Fantastic and compelling image -- beautifully stylized.', '2014-09-19 15:45:57.000000', NULL, 0),
(7264493, 1129432, 19825, '<td valign="top">This is very cool. A beauty.</td>', 'This is very cool. A beauty.', '2014-09-19 15:46:35.000000', NULL, 0),
(7264511, 1129339, 116730, '<td valign="top">The ones who I thought should win have definitely won. Congrats! Love this image.</td>', 'The ones who I thought should win have definitely won. Congrats! Love this image.', '2014-09-19 18:12:55.000000', NULL, 0),
(7264512, 1129619, 116730, '<td valign="top">Well deserved blue, sir. Like I said before, there were few to me who actually submitted "propaganda" posters...This was my favorite. AWESOME!</td>', 'Well deserved blue, sir. Like I said before, there were few to me who actually submitted "propaganda" posters...This was my favorite. AWESOME!', '2014-09-19 18:13:58.000000', NULL, 0),
(7264513, 1129270, 116730, '<td valign="top">Loved this too. So glad you got 3rd!</td>', 'Loved this too. So glad you got 3rd!', '2014-09-19 18:14:28.000000', NULL, 0),
(7264546, 1129270, 59029, '<td valign="top">Great work George, huge congrats on the first ribbon! Make sure you increase your son''s allowance ;-) Heil DPC!</td>', 'Great work George, huge congrats on the first ribbon! Make sure you increase your son''s allowance ;-) Heil DPC!', '2014-09-19 21:43:13.000000', NULL, 0),
(7264547, 1129270, 59029, '<td valign="top">*double post*<br/><br/><i>Message edited by author 2014-09-19 20:49:13.</i></td>', '*double post*', '2014-09-19 21:43:58.000000', '2014-09-19 21:49:13.000000', 0),
(7264548, 1129339, 59029, '<td valign="top">My only 10 in this challenge, so glad to see it on the front page.  Gorgeous work and love the sentiment.  Congrats on the red!</td>', 'My only 10 in this challenge, so glad to see it on the front page.  Gorgeous work and love the sentiment.  Congrats on the red!', '2014-09-19 21:47:14.000000', NULL, 0),
(7264549, 1129619, 59029, '<td valign="top">Congrats on the blue yet again Mr <strike>Lundgren</strike> err, Kiciak...and as always I love to read your shoot notes and follow your thought processes.  Fascinating as always.</td>', 'Congrats on the blue yet again Mr Lundgren err, Kiciak...and as always I love to read your shoot notes and follow your thought processes.  Fascinating as always.', '2014-09-19 21:51:31.000000', NULL, 0),
(7264550, 1129270, 163081, '<td valign="top">Many thanks for all the nice comments.<br/>My son is only 5, but I will introduce him soon with photography. He already uses my old Canon G9 (he shoots all his precious things, LOL)<br/>When I had this poster in mind I wanted to make it WW2 German style. Very often I read about the DPC admins as being hard. Still had to be fun. My PS skills are not comparable to Gyaban or other masters here at DPC. But I was satisfied with the final result. <br/>I have now a blue, red, and yellow ribbon :) Couldn''t imagine this possible when I registered few months ago.<br/></td>', 'Many thanks for all the nice comments.My son is only 5, but I will introduce him soon with photography. He already uses my old Canon G9 (he shoots all his precious things, LOL)When I had this poster in mind I wanted to make it WW2 German style. Very often I read about the DPC admins as being hard. Still had to be fun. My PS skills are not comparable to Gyaban or other masters here at DPC. But I was satisfied with the final result. I have now a blue, red, and yellow ribbon :) Couldn''t imagine this possible when I registered few months ago.', '2014-09-19 22:00:24.000000', NULL, 0),
(7264567, 1129578, 62357, '<td valign="top">This was one of my highest scores. It''s great</td>', 'This was one of my highest scores. It''s great', '2014-09-20 01:33:01.000000', NULL, 0),
(7264592, 1129270, 113016, '<td valign="top">Congrats George.  Beautifully done!</td>', 'Congrats George.  Beautifully done!', '2014-09-20 11:29:13.000000', NULL, 0),
(7264593, 1129648, 113016, '<td valign="top">another wonderful portrait from you johanna.  his expression made me smile after reading in the notes of his love for brocc.</td>', 'another wonderful portrait from you johanna.  his expression made me smile after reading in the notes of his love for brocc.', '2014-09-20 11:32:41.000000', NULL, 0),
(7264595, 1129647, 113016, '<td valign="top">this was another of my favorites this round.  love the design and editing of the text.  really love the arm/hand inserted for the ''I''.  Another great piece, Mark.  Your work in among those that I search out every challenge and find inspiration from.</td>', 'this was another of my favorites this round.  love the design and editing of the text.  really love the arm/hand inserted for the ''I''.  Another great piece, Mark.  Your work in among those that I search out every challenge and find inspiration from.', '2014-09-20 11:38:38.000000', NULL, 0),
(7264596, 1129635, 113016, '<td valign="top">wonderful message and design.</td>', 'wonderful message and design.', '2014-09-20 11:40:18.000000', NULL, 0),
(7264597, 1129660, 113016, '<td valign="top">although it didn''t say Propaganda Poster to me personally, I absolutely loved the look of this.  It really hit the era in it''s feel and look.</td>', 'although it didn''t say Propaganda Poster to me personally, I absolutely loved the look of this.  It really hit the era in it''s feel and look.', '2014-09-20 11:42:07.000000', NULL, 0),
(7264598, 1129456, 113016, '<td valign="top">Fun stuff!  I love the texture and de-sat look.  Has a wonderful rural feel to it.  I wish the text was larger to emphasize the message.</td>', 'Fun stuff!  I love the texture and de-sat look.  Has a wonderful rural feel to it.  I wish the text was larger to emphasize the message.', '2014-09-20 11:45:29.000000', NULL, 0),
(7264599, 1129339, 135629, '<td valign="top">Definitely gave this a 10, well done, love the sentiment as well.</td>', 'Definitely gave this a 10, well done, love the sentiment as well.', '2014-09-20 11:47:38.000000', NULL, 0),
(7264601, 1129619, 135629, '<td valign="top">Very well done, the lighting, clarity of the image, and composition of the poster design - all great. I gave this a 10 in voting.</td>', 'Very well done, the lighting, clarity of the image, and composition of the poster design - all great. I gave this a 10 in voting.', '2014-09-20 11:48:53.000000', NULL, 0),
(7264602, 1129549, 113016, '<td valign="top">a perfect example of todays propaganda posters.  Terrific display of the message.  it''s just waiting for someone to license it and use it.  Nice!</td>', 'a perfect example of todays propaganda posters.  Terrific display of the message.  it''s just waiting for someone to license it and use it.  Nice!', '2014-09-20 11:48:54.000000', NULL, 0),
(7264603, 1129270, 135629, '<td valign="top">I have to agree that this was very well executed in vintage style. Congrats on 3rd!</td>', 'I have to agree that this was very well executed in vintage style. Congrats on 3rd!', '2014-09-20 11:50:08.000000', NULL, 0),
(7264604, 1129648, 135629, '<td valign="top">Very well done, congrats on 4th. One ''but if'' - the distance between his arm on the left side of the photograph and the image edge nabbed my eye before I looked over the rest of the photo. I revisited it and find that to be something that immediately steals your eye from the overall image, could just be me - probably why I still gave this a 9 in voting, and definatley expected it to be in the top 5.</td>', 'Very well done, congrats on 4th. One ''but if'' - the distance between his arm on the left side of the photograph and the image edge nabbed my eye before I looked over the rest of the photo. I revisited it and find that to be something that immediately steals your eye from the overall image, could just be me - probably why I still gave this a 9 in voting, and definatley expected it to be in the top 5.', '2014-09-20 11:53:42.000000', NULL, 0),
(7264612, 1129339, 117534, '<td valign="top">Lots of talk here in MO about this, we know it''s a photo, but the most amazing job of editing Ever!!!!  Not to mention a fantastic statement about freedom of rights for photographers!!!  Congrats!!!!</td>', 'Lots of talk here in MO about this, we know it''s a photo, but the most amazing job of editing Ever!!!!  Not to mention a fantastic statement about freedom of rights for photographers!!!  Congrats!!!!', '2014-09-20 12:06:36.000000', NULL, 0),
